s.update(author='Christine Hayes',year='Fall 2006 course',reviewed='2026-10-05: Relevant published transcript sections on Joshua’s structure, conquest claims, and remaining populations reviewed.');sources.append(s)
s=source('lds-joshua','Joshua 1–24: The Entry into the Promised Land','https://www.churchofjesuschrist.org/study/manual/old-testament-student-manual-genesis-2-samuel/joshua-1-24-the-entry-into-the-promised-land?lang=eng','The manual studies Joshua’s leadership, Rahab, covenant signs, inheritance, the altar dispute, and the final choice to serve God.','LDS study manual','lds',limits='This is 1980 Institute commentary. Its historical and physical explanations are not independent archaeology or astronomy. Its ancient punishment discussion is not a present instruction.')
