active={'joshua':('Leader after Moses','He leads the crossing, campaigns, allotments, and covenant assembly.'),'caleb':('Claimant of Hebron','He recalls the scouting mission and asks Joshua for Hebron.'),'eleazar':('Priest at the allotments','He helps oversee inheritance and dies at the book’s close.'),'phinehas':('Leader of the altar inquiry','He leads the delegation that hears the eastern tribes’ explanation.')}
chapters=[]
for n,row in enumerate(rows,1):
 title,summary,meaning,pids,locs,lds=row.split('|');locs=locs.split(',')
 refs=['web','yale-12','atlas-canaan']+(['hazor-study','hazor-project'] if n==11 else [])
 route={3:['shittim','jordan'],4:['jordan','gilgal'],10:['gilgal','gibeon','beth-horon','azekah'],22:['shiloh','gilead']}.get(n,[])
 chapters.append(dict(chapter=n,title=title,summary=summary,meaning=meaning,people=pids.split(','),places=locs,sourceIds=refs,lds=dict(text=lds,sourceIds=['lds-joshua']),eventOrder=n,dateLabel='Chapter order · historical year uncertain',historicalNote='Read the biblical account beside independent evidence. A named place does not prove an event or date.',mapNote='Markers show named places and approximate regions. They do not establish exact campaign roads, tribal boundaries, or the date of a conquest.',route=route,routeEvidence='A simplified line connects the named sequence in this chapter. It omits uncertain intermediate places and does not trace an excavated road.'))
text=scripture('joshua','JOS',24)
new_ids={r[0] for r in new}
for c in chapters:
 chapter_text=' '.join(v['text'] for v in text[str(c['chapter'])])
 for p in people:
  if p['id'] in new_ids:continue
  name=p['name'].split(' / ')[0]
  if re.search(r'\b'+re.escape(name)+r'\b',chapter_text) and p['id'] not in c['people']:c['people'].append(p['id'])
for p in people:
 pid=p['id'];chap=[str(c['chapter']) for c in chapters if pid in c['people']]
 p.update(placeIds=[],linkNames=[],sourceIds=['web'],life='Historical birth and death years are not securely known.')
 p['placeIds']={'joshua':['shittim','gilgal','shiloh','shechem'],'rahab':['jericho'],'caleb':['hebron'],'othniel':['debir-town'],'achsah':['debir-town'],'eleazar':['shiloh'],'phinehas':['gilead'],'adoni-zedek':['jerusalem'],'hoham':['hebron'],'piram':['jarmuth'],'japhia':['lachish'],'jabin-joshua':['hazor']}.get(pid,[])
 if pid not in {r[0] for r in new}:
  p['passages']='Joshua '+', '.join(chap)
  if pid in active:p['role'],p['meaning']=active[pid]
  elif pid in ['mahlah','noah-daughter','hoglah','milcah-daughter','tirzah']:
   p['role']='Daughter of Zelophehad who receives inheritance';p['meaning']='She receives an inheritance under the earlier ruling. This book records the allocation, not a new legal petition.'
  elif pid in ['reuben','simeon','levi','judah','benjamin','ephraim','manasseh','zebulun','issachar','dan','naphtali','gad','asher','joseph']:
   p['role']='Ancestor recalled through a tribal name';p['meaning']='The name identifies an ancestral line or tribal community. The portrait does not place the ancestor at the allotment assembly.'
  else:p['meaning']='The book recalls this earlier figure. The reference does not place that person in Joshua’s present assembly.'
 if pid in ['jacob','esau','abraham']:p['name']=p['name'].split(' / ')[0]
finish(dict(id='joshua',bibleCode='JOS',name='Joshua',description='Crossing · campaigns · inheritance · covenant',chapterCount=24,scripture=text,chapters=chapters,people=people,places=places,sources=sources,review=dict(date='2026-10-05',scope='Chapter-level events and selected named people. Campaign claims remain separate from site evidence. Tribal portraits recall ancestors.',nextBook='judges')))

